import argparse
import csv
import json
from datetime import datetime, timezone

def parse_timestamp(timestamp_str):
    # Handle 'Z' for UTC
    if timestamp_str.endswith('Z'):
        timestamp_str = timestamp_str[:-1] + '+00:00'
    return datetime.fromisoformat(timestamp_str)

def main():
    parser = argparse.ArgumentParser(
        description='Process payment transactions from a CSV file and produce a JSON summary.'
    )
    parser.add_argument('csv_file', help='Path to the input CSV file.')

    args = parser.parse_args()

    transactions = []
    try:
        with open(args.csv_file, mode='r', newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            for i, row in enumerate(reader):
                try:
                    tx_id = row['tx_id']
                    timestamp_str = row['timestamp']
                    amount = int(row['amount'])
                    status = row['status']

                    # Store original row index for tie-breaking same-instant timestamps
                    transactions.append({
                        'tx_id': tx_id,
                        'timestamp': parse_timestamp(timestamp_str),
                        'amount': amount,
                        'status': status,
                        'original_index': i  # Keep track of original order
                    })
                except (ValueError, KeyError) as e:
                    # Skip malformed rows, or log if necessary for a real app
                    continue
    except FileNotFoundError:
        print(f"Error: CSV file '{args.csv_file}' not found.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"An error occurred while reading the CSV: {e}", file=sys.stderr)
        sys.exit(1)

    # Deduplicate: Keep latest timestamp, then latest record in CSV
    deduplicated_transactions = {}
    for tx in transactions:
        tx_id = tx['tx_id']
        if tx_id not in deduplicated_transactions:
            deduplicated_transactions[tx_id] = tx
        else:
            existing_tx = deduplicated_transactions[tx_id]
            if tx['timestamp'] > existing_tx['timestamp']:
                deduplicated_transactions[tx_id] = tx
            elif tx['timestamp'] == existing_tx['timestamp']:
                # If timestamps are identical, retain the record appearing later in the CSV
                if tx['original_index'] > existing_tx['original_index']:
                    deduplicated_transactions[tx_id] = tx

    total_valid_amount = 0
    valid_count = 0
    failed_count = 0

    for tx in deduplicated_transactions.values():
        if tx['status'] == 'VALID':
            total_valid_amount += tx['amount']
            valid_count += 1
        elif tx['status'] == 'FAILED':
            failed_count += 1
        # PENDING transactions are excluded from all summary calculations

    output_summary = {
        'total_valid_amount': total_valid_amount,
        'valid_count': valid_count,
        'failed_count': failed_count
    }

    print(json.dumps(output_summary))

if __name__ == '__main__':
    main()
